package app.daemon.deck;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.media.*;import org.json.*;
public class Alarms {
 static final String CHANNEL="mission_alarms_v2";
 static PendingIntent pending(Context c,JSONObject a)throws Exception{return PendingIntent.getBroadcast(c,0,new Intent(c,AlarmReceiver.class).setData(Uri.parse("daemon://alarm/"+Uri.encode(a.getString("id")))).putExtra("title",a.getString("title")).putExtra("body",a.getString("body")),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static synchronized String set(Context c,String json){try{JSONArray next=new JSONArray(json);if(next.length()>60000)throw new Exception("Too many alarms");AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);JSONArray old=new JSONArray(c.getSharedPreferences("alarms",0).getString("plan","[]"));for(int i=0;i<old.length();i++)am.cancel(pending(c,old.getJSONObject(i)));c.getSharedPreferences("alarms",0).edit().putString("plan",json).commit();if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())return "Exact alarm access required.";for(int i=0;i<next.length();i++){JSONObject a=next.getJSONObject(i);long at=a.getLong("at");if(at>System.currentTimeMillis())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c,a));}return "";}catch(Exception e){return "Alarm scheduling failed: "+e.getMessage();}}
 public static void restore(Context c){set(c,c.getSharedPreferences("alarms",0).getString("plan","[]"));}
 public static void channel(Context c){NotificationChannel ch=new NotificationChannel(CHANNEL,"Mission alarms",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Mission deadlines and pre-reminders");ch.enableVibration(true);ch.setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);}
}
